use std::ops::Deref;

use ruff_python_trivia::Cursor;
use ruff_text_size::{TextLen, TextSize};

/// Cursor over the remaining source of a PEP 723 script comment block.
pub(crate) struct ScriptTagCursor<'a> {
    pub(crate) text: &'a str,
    pub(crate) offset: TextSize,
    pub(crate) offset_back: TextSize,
    pub(crate) line_start: TextSize,
    pub(crate) line_end: TextSize,
}

impl<'a> ScriptTagCursor<'a> {
    pub(crate) fn new(text: &'a str, offset: TextSize) -> Self {
        let text_len = text.text_len();
        Self {
            text,
            offset,
            offset_back: offset + text_len,
            line_start: offset,
            line_end: offset,
        }
    }
}

/// Returns the body of a PEP 723 embedded content line, if `line` is a valid
/// script-comment line.
pub(crate) fn script_tag_line_body(line: &str) -> Option<&str> {
    let mut cursor = Cursor::new(line);
    if !cursor.eat_char('#') {
        return None;
    }
    if cursor.is_eof() {
        return Some("");
    }
    if !cursor.eat_char(' ') {
        return None;
    }
    Some(cursor.as_str())
}

/// A shebang directive (e.g., `#!/usr/bin/env python3`).
#[derive(Debug, PartialEq, Eq)]
pub(crate) struct ShebangDirective<'a>(&'a str);

impl<'a> ShebangDirective<'a> {
    /// Parse a shebang directive from a line, or return `None` if the line does not contain a
    /// shebang directive.
    pub(crate) fn try_extract(line: &'a str) -> Option<Self> {
        let mut cursor = Cursor::new(line);

        // Trim the `#!` prefix.
        if !cursor.eat_char('#') {
            return None;
        }
        if !cursor.eat_char('!') {
            return None;
        }

        Some(Self(cursor.chars().as_str()))
    }
}

impl Deref for ShebangDirective<'_> {
    type Target = str;

    fn deref(&self) -> &Self::Target {
        self.0
    }
}

#[cfg(test)]
mod tests {
    use insta::assert_debug_snapshot;

    use super::ShebangDirective;

    #[test]
    fn shebang_non_match() {
        let source = "not a match";
        assert_debug_snapshot!(ShebangDirective::try_extract(source));
    }

    #[test]
    fn shebang_end_of_line() {
        let source = "print('test')  #!/usr/bin/python";
        assert_debug_snapshot!(ShebangDirective::try_extract(source));
    }

    #[test]
    fn shebang_match() {
        let source = "#!/usr/bin/env python";
        assert_debug_snapshot!(ShebangDirective::try_extract(source));
    }

    #[test]
    fn shebang_match_trailing_comment() {
        let source = "#!/usr/bin/env python # trailing comment";
        assert_debug_snapshot!(ShebangDirective::try_extract(source));
    }

    #[test]
    fn shebang_leading_space() {
        let source = "  #!/usr/bin/env python";
        assert_debug_snapshot!(ShebangDirective::try_extract(source));
    }
}

